/**
 * Shareable boards. A board travels in a URL parameter as base64url JSON and is
 * strictly validated on the way in: unknown fields are ignored, ids must match
 * Gridiron's formats, names are cleaned and every list is capped.
 */
import type { Density, Division, GameId, GameSummary, LayoutMode, LeagueId, TeamKey } from './model.js';
import { parseGameId } from './model.js';
import { isRecord } from './util.js';

export interface BoardShare {
  name: string;
  teams: TeamKey[];
  games: GameId[];
  focus: GameId[];
  league: 'all' | LeagueId;
  divisions: Division[];
  layout: LayoutMode;
  density: Density;
}

export const BOARD_PARAM = 'board';
const MAX_ENCODED = 4096;
const TEAM_KEY = /^(nfl|cfb)-[A-Za-z0-9]{1,16}$/;
const DIVISIONS: Division[] = ['NFL', 'FBS', 'FCS', 'D2', 'D3'];

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(value: string): string {
  const padded = value.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((value.length + 3) % 4);
  const bin = atob(padded);
  return new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

export function sanitizeBoardName(name: unknown): string {
  if (typeof name !== 'string') return 'Shared board';
  const clean = name
    .replace(/[�--​-‏‪-‮⁦-⁩﻿]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return Array.from(clean).slice(0, 60).join('') || 'Shared board';
}

function uniqueValid<T extends string>(value: unknown, valid: (v: string) => boolean, max: number): T[] {
  if (!Array.isArray(value)) return [];
  const out: T[] = [];
  for (const v of value) {
    if (out.length >= max) break;
    if (typeof v === 'string' && valid(v) && !out.includes(v as T)) out.push(v as T);
  }
  return out;
}

export function encodeBoard(board: BoardShare): string {
  return toBase64Url(
    JSON.stringify({
      v: 1,
      n: sanitizeBoardName(board.name),
      t: board.teams.slice(0, 64),
      g: board.games.slice(0, 64),
      f: board.focus.slice(0, 4),
      l: board.league,
      d: board.divisions,
      y: board.layout,
      e: board.density,
    }),
  );
}

export function decodeBoard(param: string | null | undefined): BoardShare | null {
  if (!param || param.length > MAX_ENCODED || !/^[A-Za-z0-9_-]+$/.test(param)) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(fromBase64Url(param));
  } catch {
    return null;
  }
  if (!isRecord(raw) || raw.v !== 1) return null;
  const isGame = (v: string) => parseGameId(v) !== null;
  return {
    name: sanitizeBoardName(raw.n),
    teams: uniqueValid<TeamKey>(raw.t, (v) => TEAM_KEY.test(v), 64),
    games: uniqueValid<GameId>(raw.g, isGame, 64),
    focus: uniqueValid<GameId>(raw.f, isGame, 4),
    league: raw.l === 'nfl' || raw.l === 'cfb' ? raw.l : 'all',
    divisions: uniqueValid<Division>(raw.d, (v) => (DIVISIONS as string[]).includes(v), DIVISIONS.length),
    layout: raw.y === 'focus' || raw.y === 'wall' ? raw.y : 'slate',
    density: raw.e === 'compact' ? 'compact' : 'comfortable',
  };
}

/**
 * The games a board shows for the selected day: its pinned games in their saved
 * order, then every game involving one of its teams, by kickoff. Team boards
 * therefore follow their teams from day to day.
 */
export function resolveBoardGames(board: Pick<BoardShare, 'teams' | 'games'>, games: GameSummary[]): GameSummary[] {
  const byId = new Map(games.map((g) => [g.id, g]));
  const out: GameSummary[] = [];
  const seen = new Set<GameId>();
  for (const id of board.games) {
    const g = byId.get(id);
    if (g && !seen.has(id)) {
      out.push(g);
      seen.add(id);
    }
  }
  const teams = new Set(board.teams);
  const teamGames = games
    .filter((g) => !seen.has(g.id) && (teams.has(g.home.key) || teams.has(g.away.key)))
    .sort((a, b) => (a.startTime ?? '').localeCompare(b.startTime ?? '') || a.id.localeCompare(b.id));
  return [...out, ...teamGames];
}
